      'name: severity-based-routing\ndescription: Route log messages based on severity level\ntype: pipeline\nnamespace: production\nlabels:\n  environment: production\n  pattern: content-routing\n\nconfig:\n  input:\n    http_server:\n      address: 0.0.0.0:8080\n      path: /logs\n      timeout: 5s\n\n  pipeline:\n    processors:\n      # Parse JSON input and validate\n      - mapping: |\n          root = if this.severity == null {\n            throw("Missing required field: severity")\n          } else {\n            this\n          }\n\n          # Normalize severity to uppercase\n          root.severity = this.severity.string().uppercase()\n\n          # Add routing metadata\n          root.routed_at = now()\n          root.node_id = env("NODE_ID").or("unknown")\n\n  output:\n    switch:\n      cases:\n        # Case 1: Critical errors to PagerDuty\n        - check: this.severity == "CRITICAL" || this.severity == "FATAL"\n          output:\n            # PagerDuty Events API v2 envelope. The routing key is the\n            # integration credential and belongs in the request body.\n            processors:\n              - mapping: |\n                  root.routing_key = env("PAGERDUTY_ROUTING_KEY")\n                  root.event_action = "trigger"\n                  root.dedup_key = this.event_id.or(uuid_v4())\n                  root.payload = {\n                    "summary": this.message.or("Critical error occurred"),\n                    "severity": "critical",\n                    "source": this.source.or("unknown"),\n                    "timestamp": this.timestamp,\n                    "custom_details": this\n                  }\n            http_client:\n              url: https://events.pagerduty.com/v2/enqueue\n              verb: POST\n              headers:\n                Content-Type: application/json\n              retries: 5\n              retry_period: 500ms\n              max_retry_backoff: 5s\n\n        # Case 2: Warnings to Slack\n        - check: this.severity == "WARNING" || this.severity == "WARN"\n          output:\n            processors:\n              - mapping: |\n                  root.text = ":warning: " + this.message.or("Warning")\n                  root.blocks = [\n                    {\n                      "type": "section",\n                      "text": {\n                        "type": "mrkdwn",\n                        "text": "*Severity:* " + this.severity + "\\n*Source:* " + this.source.or("unknown") + "\\n*Message:* " + this.message.or("N/A")\n                      }\n                    }\n                  ]\n            http_client:\n              url: ${SLACK_HTTPS_WEBHOOK_URL}\n              verb: POST\n              headers:\n                Content-Type: application/json\n              retries: 3\n              tls:\n                enabled: true\n\n        # Case 3: Everything else to the Elasticsearch document API\n        - output:\n            http_client:\n              url: \'${ELASTICSEARCH_HTTPS_URL}/logs-${! now().ts_format("2006-01-02") }/_doc/${! this.event_id.or(uuid_v4()) }\'\n              verb: PUT\n              headers:\n                Authorization: \'ApiKey ${ELASTICSEARCH_API_KEY}\'\n                Content-Type: application/json\n              tls:\n                enabled: true\n                root_cas_file: ${ELASTICSEARCH_CA_FILE}\n              retries: 3\n              retry_period: 1s\n              max_retry_backoff: 30s\n',
