    fullYamlFilename: "content-splitting.yaml",
    fullYaml:
      'name: split-sensor-array\ndescription: Split sensor reading arrays into individual messages\ntype: pipeline\nnamespace: production\n\nconfig:\n  input:\n    http_server:\n      address: 0.0.0.0:8080\n      path: /sensors/bulk\n      timeout: 5s\n\n  pipeline:\n    processors:\n      # Step 1: Store parent context in metadata BEFORE splitting\n      - mapping: |\n          meta device_id = this.device_id\n          meta batch_timestamp = this.timestamp\n          root = this\n\n      # Step 2: Validate structure\n      - mapping: |\n          root = if this.readings == null || this.readings.type() != "array" {\n            throw("Missing or invalid readings array")\n          } else {\n            this.readings\n          }\n\n      # Step 3: Split the readings array into individual messages\n      - unarchive:\n          format: json_array\n\n      # Step 4: Enrich each split message with parent context\n      - mapping: |\n          root = this\n          root.device_id = meta("device_id")\n          root.batch_timestamp = meta("batch_timestamp")\n          root.edge_node = env("NODE_ID").or("unknown")\n          root.processed_at = now()\n\n  output:\n    switch:\n      cases:\n        # Critical: High temperature alert\n        - check: this.value > 80.0 && this.unit == "F"\n          output:\n            http_client:\n              url: ${ALERT_SERVICE_HTTPS_URL}/critical-temp\n              verb: POST\n              headers:\n                Content-Type: application/json\n                Authorization: \'Bearer ${ALERT_SERVICE_TOKEN}\'\n              retries: 5\n              tls:\n                enabled: true\n\n        # Warning: Elevated temperature\n        - check: this.value > 70.0 && this.value <= 80.0 && this.unit == "F"\n          output:\n            kafka:\n              addresses: [\'${KAFKA_TLS_BROKERS}\']\n              topic: elevated-temp-warnings\n              tls:\n                enabled: true\n                root_cas_file: ${KAFKA_CA_FILE}\n              sasl:\n                mechanism: SCRAM-SHA-512\n                user: \'${KAFKA_USERNAME}\'\n                password: \'${KAFKA_PASSWORD}\'\n              batching:\n                count: 50\n                period: 30s\n\n        # Normal: Archive for analytics\n        - output:\n            file:\n              path: ${SENSOR_ARCHIVE_PATH}/normal-${!timestamp_unix_date("2006-01-02")}.jsonl\n              codec: lines\n',
