      'name: multi-destination-sensor-data\ndescription: Send sensor data to authenticated Kafka, encrypted S3, and authenticated Elasticsearch\ntype: pipeline\nnamespace: production\nlabels:\n  environment: production\n  data-type: sensor-metrics\nconfig:\n  input:\n    http_server:\n      address: 0.0.0.0:8080\n      path: /events\n      allowed_verbs:\n        - POST\n  pipeline:\n    processors:\n      - mapping: |\n          root = this\n          root.processed_at = now()\n          root.node_id = env("NODE_ID").or("unknown")\n  output:\n    broker:\n      pattern: fan_out\n      outputs:\n        - kafka:\n            addresses:\n              - ${KAFKA_TLS_BROKERS}\n            topic: sensor-events\n            key: ${! this.sensor_id }\n            tls:\n              enabled: true\n              root_cas_file: ${KAFKA_CA_FILE}\n            sasl:\n              mechanism: SCRAM-SHA-512\n              user: ${KAFKA_USERNAME}\n              password: ${KAFKA_PASSWORD}\n            ack_replicas: true\n            batching:\n              count: 100\n              period: 5s\n        - aws_s3:\n            bucket: ${S3_BUCKET}\n            region: ${AWS_REGION}\n            path: events/date=${! now().ts_format("2006-01-02") }/${! uuid_v4() }.json\n            content_type: application/json\n            storage_class: INTELLIGENT_TIERING\n            server_side_encryption: aws:kms\n            kms_key_id: ${S3_KMS_KEY_ARN}\n            batching:\n              count: 100\n              period: 30s\n        - http_client:\n            url: ${ELASTICSEARCH_HTTPS_URL}/sensor-events-${! now().ts_format("2006-01-02") }/_doc/${! this.event_id.or(uuid_v4()) }\n            verb: PUT\n            headers:\n              Authorization: ApiKey ${ELASTICSEARCH_API_KEY}\n              Content-Type: application/json\n            tls:\n              enabled: true\n              root_cas_file: ${ELASTICSEARCH_CA_FILE}\n        - file:\n            path: ${FAN_OUT_DIAGNOSTIC_PATH}/events.jsonl\n            codec: lines\n',
