    fullYamlFilename: "enforce-schema.yaml",
    fullYaml:
      'name: sensor-schema-validation\ndescription: Validate sensor data against JSON Schema with DLQ for failures\ntype: pipeline\nnamespace: production\nlabels:\n  environment: production\n  data-type: sensor-readings\n  validation: enabled\npriority: 100\nselector:\n  match_labels:\n    role: sensor-collector\n    validation: required\ndeployment:\n  strategy: rolling\n  max_parallel: 2\n  health_check:\n    type: http\n    endpoint: /ping\n    interval: 30s\n  auto_rollback: true\nconfig:\n  input:\n    http_server:\n      address: 127.0.0.1:8080\n      path: /{endpoint:sensor/readings|sensors}\n      allowed_verbs:\n        - POST\n      timeout: 5s\n      rate_limit: sensor_ingest\n  pipeline:\n    processors:\n      - mapping: root = content().parse_json()\n      - mapping: |\n          root = this\n\n          # Track when message entered pipeline\n          root.pipeline_metadata = {\n            "received_at": now(),\n            "node_id": env("NODE_ID").or("unknown"),\n            "pipeline_version": "1.0.0"\n          }\n      - try:\n          - json_schema:\n              schema_path: file:///etc/expanso/schemas/sensor-schema-v1.0.0.json\n          - mapping: |\n              root = this\n              root.validation = {\n                "status": "passed",\n                "schema_version": "1.0.0",\n                "validated_at": now()\n              }\n\n              # Set metadata for routing\n              meta validation_status = "passed"\n      - catch:\n          - mapping: |\n              root = this\n\n              # Capture validation failure details\n              root.validation = {\n                "status": "failed",\n                "schema_version": "1.0.0",\n                "validated_at": now(),\n                "error": error(),\n                "error_type": "schema_validation_failed"\n              }\n\n              # Set metadata for routing to DLQ\n              meta validation_status = "failed"\n              meta validation_error = error()\n      - mapping: |\n          root = this\n\n          # Create data quality score\n          root.data_quality = {\n            "validated": true,\n            "validation_passed": meta("validation_status") == "passed",\n            "quality_score": if meta("validation_status") == "passed" { 100 } else { 0 }\n          }\n  output:\n    broker:\n      pattern: fan_out\n      outputs:\n        - label: analytics\n          switch:\n            cases:\n              - check: meta("validation_status") == "passed"\n                output:\n                  http_client:\n                    url: ${ANALYTICS_HTTPS_URL}/ingest\n                    verb: POST\n                    headers:\n                      Content-Type: application/json\n                      Authorization: Bearer ${ANALYTICS_API_TOKEN}\n                    batching:\n                      count: 100\n                      period: 5s\n                    tls:\n                      enabled: true\n                    retries: 3\n                    retry_period: 1s\n                    max_retry_backoff: 30s\n              - output:\n                  drop: {}\n        - label: dead_letter_queue\n          switch:\n            cases:\n              - check: meta("validation_status") == "failed"\n                output:\n                  file:\n                    path: ${SCHEMA_DLQ_PATH}/schema-validation-${! timestamp_unix() }.jsonl\n                    codec: lines\n              - output:\n                  drop: {}\n        - label: metrics\n          processors:\n            - mapping: |\n                let validation_error = meta("validation_error")\n                root = {\n                  "timestamp": now(),\n                  "node_id": env("NODE_ID").or("unknown"),\n                  "validation_status": meta("validation_status"),\n                  "sensor_id": this.sensor_id.or("unknown"),\n                  "error": if meta("validation_status") == "failed" {\n                    $validation_error\n                  }\n                }\n          http_client:\n            url: ${METRICS_HTTPS_URL}/validation\n            verb: POST\n            headers:\n              Content-Type: application/json\n              Authorization: Bearer ${METRICS_API_TOKEN}\n            batching:\n              count: 100\n              period: 10s\n            tls:\n              enabled: true\n            retries: 0\n  rate_limit_resources:\n    - label: sensor_ingest\n      local:\n        count: 1000\n        interval: 1s\nlogger:\n  level: INFO\n  format: json\n  add_timestamp: true\nmetrics:\n  prometheus:\n    path: /metrics\n  mapping: |\n    root = this\n    meta pipeline = "schema-validation"\n    meta validation = "enabled"\n',
