      'name: multi-format-log-parser\ndescription: Parse structured JSON, Apache, syslog, and CSV records at the edge.\ntype: pipeline\nnamespace: examples\nlabels:\n  category: data-transformation\n  pattern: multi-format-parsing\nconfig:\n  input:\n    broker:\n      inputs:\n        - file:\n            paths:\n              - ${LOG_INPUT_PATH}/*.jsonl\n            codec: lines\n        - http_server:\n            address: 127.0.0.1:8080\n            path: /logs\n            allowed_verbs:\n              - POST\n  pipeline:\n    processors:\n      - command:\n          name: uv\n          args_mapping: root = ["run", "--no-project", env("RECORD_CODECS_SCRIPT"), "parse-log"]\n      - catch:\n          - mapping: \'root = {"format": "parse_failed", "parse_error": error(), "raw_content": content().string()}\'\n      - mapping: |\n          root = this\n          root.node_id = env("NODE_ID").or("unknown")\n  output:\n    switch:\n      cases:\n        - check: this.format == "unknown" || this.format == "parse_failed"\n          output:\n            file:\n              path: ${LOG_DLQ_PATH}/unparsed.jsonl\n              codec: lines\n        - output:\n            http_client:\n              url: ${LOG_HTTPS_URL}/logs\n              verb: POST\n              headers:\n                Authorization: Bearer ${LOG_API_TOKEN}\n                Content-Type: application/json\n              tls:\n                enabled: true\n              retries: 3\n              batching:\n                count: 100\n                period: 5s\n',
