    fullYaml:
      'name: format-negotiation-and-avro\ndescription: Decode JSON, CSV, and XML, negotiate responses, and emit validated Avro records.\ntype: pipeline\nnamespace: examples\nlabels:\n  category: data-transformation\n  pattern: format-conversion\nconfig:\n  input:\n    http_server:\n      address: 127.0.0.1:8080\n      path: /{endpoint:sensors/ingest|transform}\n      allowed_verbs:\n        - POST\n      sync_response:\n        headers:\n          Content-Type: ${! meta("response_type") }\n        status: ${! meta("response_status").or("200") }\n  pipeline:\n    processors:\n      - command:\n          name: uv\n          args_mapping: root = ["run", "--no-project", env("RECORD_CODECS_SCRIPT"), "decode"]\n      - catch:\n          - mapping: root = deleted()\n  output:\n    broker:\n      pattern: fan_out\n      outputs:\n        - processors:\n            - try:\n                - command:\n                    name: uv\n                    args_mapping: root = ["run", "--no-project", env("RECORD_CODECS_SCRIPT"), "encode", meta("Accept").or("application/json")]\n                - mapping: |-\n                    meta response_type = match this.transformation.target_format { "xml" => "application/xml", "csv" => "text/csv", _ => "application/json" }\n                    root = this.data\n            - catch:\n                - mapping: |-\n                    let failure = error()\n                    root = {"error": $failure}\n                    meta response_type = "application/json"\n                    meta response_status = "422"\n          sync_response: {}\n        - switch:\n            cases:\n              - check: this.data.sensor_id != null && this.data.metadata != null\n                output:\n                  kafka:\n                    addresses:\n                      - ${KAFKA_TLS_BROKERS}\n                    topic: sensor-readings-avro\n                    tls:\n                      enabled: true\n                      root_cas_file: ${KAFKA_CA_FILE}\n                    sasl:\n                      mechanism: SCRAM-SHA-512\n                      user: ${KAFKA_USERNAME}\n                      password: ${KAFKA_PASSWORD}\n                    compression: snappy\n                    batching:\n                      count: 100\n                      period: 5s\n                  processors:\n                    - try:\n                        - mapping: root = this.data\n                        - mapping: |\n                            root.sensor_id = this.sensor_id\n                            root.location = this.location\n                            root.temperature = this.temperature\n                            root.humidity = this.humidity\n                            root.timestamp = this.timestamp\n                            root.device_type = this.metadata.device_type\n                            root.firmware_version = this.metadata.firmware_version\n                        - command:\n                            name: uv\n                            args_mapping: root = ["run", "--no-project", env("RECORD_CODECS_SCRIPT"), "avro"]\n                        - mapping: root = this.avro_base64.decode("base64")\n                    - catch:\n                        - mapping: root = deleted()\n              - output:\n                  drop: {}\n',
