        yamlCode:
          'pipeline:\n  processors:\n    # Step 3: Mask account numbers for compliance\n    # Keep last 4 digits for reconciliation, hash full number for joins\n    - mapping: |\n        root = this\n        root.account_number_masked = "****-****-" + this.ACCOUNT_NUMBER.slice(-4)\n        root.account_number_hash = this.ACCOUNT_NUMBER.hash("sha256").encode("hex").slice(0, 16)\n        root = root.without("ACCOUNT_NUMBER")\n',
        configSha256:
          "sha256:866eb7798374e193199a3070220c4c2fe93b7c6537f720a40800902a657e2232",
