          'output:\n  switch:\n    cases:\n      - check: this._table == "orders"\n        output:\n          gcp_cloud_storage:\n            bucket: ${GCS_BACKUP_BUCKET}\n            path: backups/orders/${! meta("backup_date") }/orders-${!uuid_v4()}.parquet\n            content_type: application/octet-stream\n            batching:\n              count: 10000\n              period: 60s\n              processors:\n                - mapping: |\n                    meta backup_date = this._backup_metadata.backup_date\n                    root.record = this.format_json()\n                - parquet_encode:\n                    default_compression: snappy\n                    schema:\n                      - name: record\n                        type: UTF8\n      - check: this._table == "inventory"\n        output:\n          gcp_cloud_storage:\n            bucket: ${GCS_BACKUP_BUCKET}\n            path: backups/inventory/${! meta("backup_date")\n              }/inventory-full-${!uuid_v4()}.parquet\n            content_type: application/octet-stream\n            batching:\n              count: 50000\n              period: 120s\n              processors:\n                - mapping: |\n                    meta backup_date = this._backup_metadata.backup_date\n                    root.record = this.format_json()\n                - parquet_encode:\n                    default_compression: snappy\n                    schema:\n                      - name: record\n                        type: UTF8\n      - check: this._table == "order_items"\n        output:\n          gcp_cloud_storage:\n            bucket: ${GCS_BACKUP_BUCKET}\n            path: backups/order_items/${! meta("backup_date") }/items-${!uuid_v4()}.parquet\n            content_type: application/octet-stream\n            batching:\n              count: 10000\n              period: 60s\n              processors:\n                - mapping: |\n                    meta backup_date = this._backup_metadata.backup_date\n                    root.record = this.format_json()\n                - parquet_encode:\n                    default_compression: snappy\n                    schema:\n                      - name: record\n                        type: UTF8\n      - output:\n          gcp_cloud_storage:\n            bucket: ${GCS_BACKUP_BUCKET}\n            path: backups/unknown/${!this._table}/${!this._backup_metadata.backup_date}/data-${!timestamp_unix()}.json\n            content_type: application/json\n            batching:\n              count: 1000\n              period: 30s\n',
