              "PTP4L_OFFSET=156ns;CPU_PERCENT=89.4;PRB_DL_UTIL=95.7;PRB_UL_UTIL=88.2;RSRP=-102dBm;SINR=12.1dB;TIMESTAMP=1705315875",
