        yamlCode:
          'pipeline:\n  processors:\n    - mapping: |\n        # Parse syslog timestamp and message structure\n        let raw = content().string()\n        let parts = $raw.re_find_all_submatch(\n          "^(\\\\d{4}-\\\\d{2}-\\\\d{2} \\\\d{2}:\\\\d{2}:\\\\d{2}) \\\\[(INFO|WARN|ERROR|DEBUG)\\\\] \\\\[([^\\\\]]+)\\\\] (.+)$"\n        )\n        root = if $parts.length() > 0 {\n          {\n            "timestamp": $parts.index(0).index(1),\n            "level": $parts.index(0).index(2),\n            "thread": $parts.index(0).index(3),\n            "message": $parts.index(0).index(4),\n            "raw": $raw\n          }\n        } else {\n          {\n            "timestamp": now(),\n            "level": "INFO",\n            "thread": "unknown",\n            "message": $raw,\n            "raw": $raw\n          }\n        }\n',
