    canonicalPipelinePath:
      "examples/log-processing/enrich-export-complete.yaml",
    pipelineSha256:
      "sha256:70f80286106aaf629099f6fa847b2069b342ca1f98717f51529168df82196c98",
    fullYamlFilename: "enrich-export-complete.yaml",
    fullYaml:
      'name: enrich-export-complete\ntype: pipeline\ndescription: Complete example pipeline for enriching logs with metadata and exporting to Amazon S3.\nnamespace: production\nlabels:\n  category: log-processing\n  pattern: enrichment-export\nconfig:\n  input:\n    generate:\n      interval: ${GENERATE_INTERVAL:-1s}\n      # Numeric component fields are fixed values because Expanso Edge validates\n      # them before environment interpolation. Edit this value for a finite run.\n      count: 0\n      mapping: |\n        root.id = uuid_v4()\n        root.timestamp = now()\n\n        let level_random = random_int() % 100\n        root.level = if $level_random < 70 {\n          "INFO"\n        } else if $level_random < 90 {\n          "WARN"\n        } else {\n          "ERROR"\n        }\n\n        let services = [\n          {"name": "api-gateway", "weight": 30},\n          {"name": "auth-service", "weight": 20},\n          {"name": "user-service", "weight": 15},\n          {"name": "payment-service", "weight": 15},\n          {"name": "notification-service", "weight": 10},\n          {"name": "analytics-service", "weight": 10}\n        ]\n        root.service = $services.index(random_int() % 6).name\n\n        root.user_id = "user_" + (random_int() % 10000).string()\n        root.session_id = "session_" + (random_int() % 1000).string()\n        root.request_id = uuid_v4()\n        root.trace_id = uuid_v4()\n\n        root.duration_ms = random_int() % 5000 + 50\n        root.status_code = match {\n          root.level == "INFO" => [200, 201, 202, 204].index(random_int() % 4)\n          root.level == "WARN" => [400, 401, 403, 404, 429].index(random_int() % 5)\n          root.level == "ERROR" => [500, 502, 503, 504].index(random_int() % 4)\n          _ => 200\n        }\n\n        root.message = match {\n          root.service == "api-gateway" => "Request processed: " + root.status_code.string() + " in " + root.duration_ms.string() + "ms"\n          root.service == "auth-service" => if root.level == "ERROR" { "Authentication failed" } else { "User authenticated successfully" }\n          root.service == "payment-service" => if root.level == "ERROR" { "Payment processing failed" } else { "Payment processed" }\n          _ => "Service operation completed with status " + root.status_code.string()\n        }\n  pipeline:\n    processors:\n      - mapping: |\n          root = this\n          let processing_start = now()\n\n          root.lineage = {\n            "node_id": env("NODE_ID").or("edge-node-" + uuid_v4().slice(0, 8)),\n            "node_region": env("AWS_REGION").or("us-east-1"),\n            "pipeline_name": "log-enrichment-s3-production",\n            "pipeline_version": env("PIPELINE_VERSION").or("5.0.0"),\n            "processed_at": $processing_start,\n            "environment": env("ENVIRONMENT").or("production")\n          }\n      - mapping: |\n          root.event = {\n            "id": this.id.or(uuid_v4()),\n            "timestamp": this.timestamp.or(now()),\n            "type": "application_log",\n            "user_id": this.user_id,\n            "application": {\n              "service": this.service.or("unknown"),\n              "level": this.level.or("INFO"),\n              "message": this.message.or(""),\n              "duration_ms": this.duration_ms,\n              "status_code": this.status_code\n            },\n            "trace": {\n              "request_id": this.request_id.or(uuid_v4()),\n              "trace_id": this.trace_id.or(uuid_v4())\n            }\n          }\n\n          root.metadata = {\n            "lineage": this.lineage,\n            "quality": {\n              "completeness_score": (\n                (if this.user_id != null { 1 } else { 0 }) +\n                (if this.request_id != null { 1 } else { 0 }) +\n                (if this.message != null { 1 } else { 0 }) +\n                (if this.service != null { 1 } else { 0 })\n              ) / 4.0,\n              "is_error": this.level == "ERROR"\n            }\n          }\n  output:\n    broker:\n      pattern: fan_out\n      outputs:\n        - aws_s3:\n            bucket: ${S3_BUCKET_NAME}\n            path: logs/year=${!timestamp("2006")}/month=${!timestamp("01")}/day=${!timestamp("02")}/logs_${!timestamp_unix()}.jsonl.gz\n            batching:\n              count: 200\n              period: ${BATCH_PERIOD:-2m}\n              byte_size: 5242880\n              processors:\n                - compress:\n                    algorithm: gzip\n                    level: 6\n            content_type: application/x-ndjson\n            content_encoding: gzip\n            storage_class: ${S3_STORAGE_CLASS:-STANDARD_IA}\n            region: ${AWS_REGION}\n            server_side_encryption: aws:kms\n            kms_key_id: ${S3_KMS_KEY_ARN}\n        - aws_s3:\n            bucket: ${S3_ERROR_BUCKET_NAME:-${S3_BUCKET_NAME}}\n            path: errors/year=${!timestamp("2006")}/month=${!timestamp("01")}/day=${!timestamp("02")}/error_${!timestamp_unix()}.jsonl\n            batching:\n              count: 50\n              period: 1m\n            content_type: application/x-ndjson\n            storage_class: STANDARD\n            region: ${AWS_REGION}\n            server_side_encryption: aws:kms\n            kms_key_id: ${S3_KMS_KEY_ARN}\n          processors:\n            - mapping: |\n                root = if this.event.application.level == "ERROR" {\n                  this\n                } else {\n                  deleted()\n                }\nlogger:\n  level: ${LOG_LEVEL:-info}\n  format: json\nmetrics:\n  prometheus:\n    prefix: log_enrichment_prod\n',
